head.script:
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#input1').simulate('key-sequence', {
        sequence: '111111'
    });
}
scwin.checkVal = function() {
	return document.activeElement.id == $p.id+'checkbox1_input_0';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 input1의 필드에 11자리 값을 입력한다.
    //1. Run the sample file and enter the 11 digit value in the field of input1.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 2. 11자리 값이 입력되면서 focus가 체크박스로 이동되어진다.(이전에는 autofocus기능 안됨)
    //2. The 11-digit value is entered and focus is moved to the checkbox (previously no autofocus function).
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 16-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
